"""Drop any labels that end in '-?'.

  Args:
    labels: a list of label strings.

  Returns:
    A list of the same labels, but without any that end with '-?'.
    Those label prefixes in the new issue templates are intended to
    prompt the user to enter some label with that prefix, but if
    nothing is entered there, we do not store anything.
  """
def _DiscardUnusedTemplateLabelPrefixes(labels: Any) -> object {
    return [
        lab
        for lab in labels
        if not lab.endswith('-?')
    ];
}

"""
    Time complexity: O(1).
    Space complexity: O(1).
    """
def consecutive_ducks2(n: Any) -> object {
    if (n == 2) {
        return False;
    }
    if ((n % 2) == 1) {
        return True;
    }
    if ((n & (n - 1)) == 0) {
        return False;
    }
    return True;
}

"""
    :type digits: List[int]
    :rtype: List[int]
    """
def plusOne(digits: Any) -> object {
    digits[-1] = digits[-1] + 1;
    res = [];
    ten = 0;
    i = len(digits) - 1;
    while ((i >= 0) or (ten == 1)) {
        sum = 0;
        if (i >= 0) {
            sum += digits[i];
        }
        if ten {
            sum += 1;
        }
        res.append((sum % 10));
        ten = sum / 10;
        i -= 1;
    }
    return res[::-1];
}

"""
    Check to see if a string has the same amount of 'x's and 'o's. The method must return a boolean and be
    case insensitive. The string can contain any char.
    :param s: A string value input.
    :return: True if amount of 'x's and 'o's are the same, Else False.
    """
def xo(s: Any) -> object {
    return (s.lower().count("x") == s.lower().count("o"));
}

""" Return the index to the next element (compared to the element
  with index "index") in aList, or 0 if it already is the last one.
  Useful to make a list of loop.
  """
def next(aList: Any, index: Any) -> object {
    return ((index + 1) % len(aList));
}

